/// Holds the locale the application is displayed in.
///
/// A `null` state means "follow the system locale".
final class LocaleCubit extends Cubit<Locale?> {
 LocaleCubit() : super(null);

 /// Switches to the next supported locale, wrapping around to the system
 /// locale after the last one.
 void toggle() {
   final current = state;
   if (current == null) {
     emit(appSupportedLocales.first);
     return;
   }
   final index = appSupportedLocales.indexOf(current);
   emit(index + 1 < appSupportedLocales.length ? appSupportedLocales[index + 1] : null);
 }
